    if (iterator->hdr->it_version != 0)
        return -EINVAL;

    return ret;
}

int ieee80211_radiotap_iterator_init(struct ieee80211_radiotap_iterator *iterator,
                                     const struct ieee80211_radiotap_header *radiotap_header,
                                     int max_length,
                                     const struct ieee80211_radiotap_vendor_namespaces *vns) {
    /* Validate the radiotap header length */
    if (max_length < sizeof(*radiotap_header))
        return -EINVAL;

    /* Validate the version (must be 0) */
    if (radiotap_header->it_version != 0)
        return -EINVAL;

    /* Initialize the iterator */
    iterator->rtheader = radiotap_header;
    iterator->max_length = max_length;
    iterator->vns = vns;
    iterator->cursor = 0;
    iterator->current_index = 0;
    iterator->is_valid = 1;

    /* Check if the radiotap header has an extended present bitmap */
    if (iterator->rtheader->it_len >= sizeof(*radiotap_header) + sizeof(uint32_t)) {
        iterator->has_present = 1;
        iterator->present = *(uint32_t *)(((const uint8_t *)radiotap_header) + sizeof(*radiotap_header));
    } else {
        iterator->has_present = 0;
        iterator->present = 0;
    }

    return 0;
}

int ieee80211_radiotap_iterator_init(struct ieee80211_radiotap_iterator *iterator,
                                    struct ieee80211_radiotap_header *radiotap_header,
                                    int max_length,
                                    const struct ieee80211_radiotap_vendor_namespaces *vns) {
    uint8_t *cursor;
    uint32_t bitmap;

    if (!iterator || !radiotap_header)
        return -EINVAL;

    if (max_length < sizeof(*radiotap_header))
        return -EINVAL;

    if (radiotap_header->it_version != 0)
        return -EINVAL;

    iterator->header = radiotap_header;
    iterator->max_length = max_length;
    iterator->vns = vns;
    cursor = (uint8_t *)radiotap_header + sizeof(*radiotap_header);
    iterator->this_arg = cursor;
    iterator->is_last = 0;

    if (radiotap_header->it_len < sizeof(*radiotap_header))
        return -EINVAL;

    if (radiotap_header->it_pad[0] != 0 || radiotap_header->it_pad[1] != 0)
        return -EINVAL;

    bitmap = le16toh(radiotap_header->it_present);
    if (bitmap & IEEE80211_RADIOTAP_EXT)
        bitmap |= (le16toh(*((uint16_t *)((uint8_t *)radiotap_header + IEEE80211_RADIOTAP_EXT))) << 16);

    if (bitmap == 0)
        iterator->is_last = 1;

    iterator->next_bitmap = bitmap;
    iterator->cursor = cursor;

    return 0;
}

int ieee80211_radiotap_iterator_init(struct ieee80211_radiotap_iterator *iterator,
                                     struct ieee80211_radiotap_header *radiotap_header,
                                     int max_length,
                                     const struct ieee80211_radiotap_vendor_namespaces *vns) {
    int ret;

    if (!iterator || !radiotap_header) {
        return -EINVAL;
    }

    if (max_length < sizeof(*radiotap_header)) {
        return -EINVAL;
    }

    iterator->rtheader = radiotap_header;
    iterator->max_length = max_length;
    iterator->vns = vns;
    iterator->this_arg = 0;
    iterator->arg_count = 0;
    iterator->is_radiotap = 1;

    ret = ieee80211_radiotap_parse(iterator, radiotap_header, max_length, vns);
    if (ret < 0) {
        return ret;
    }

    if ((iterator->rtheader->it_version & ~IEEE80211_RADIOTAP_VERSION) != 0) {
        return -EINVAL;
    }

    if (iterator->rtheader->it_pad[0] != 0 || iterator->rtheader->it_pad[1] != 0) {
        return -EINVAL;
    }

    if ((iterator->rtheader->it_present >> (iterator->rtheader->it_len * 8)) != 0) {
        return -EINVAL;
    }

    if (iterator->rtheader->it_len < sizeof(*iterator->rtheader)) {
        return -EINVAL;
    }

    if (iterator->rtheader->it_len > max_length) {
        return -EINVAL;
    }

    if (iterator->rtheader->it_version > IEEE80211_RADIOTAP_VERSION) {
        return -EINVAL;
    }

    return 0;
}
